    assert.equal(fakeDocument.containers['error-message'].hidden, true, '加载中应隐藏错误容器');

    resolveFetch(makeOkResponse(JSON.stringify(VALID_LEVELS)));
    await done;

    assert.equal(fakeDocument.containers.loading.hidden, true, '渲染后应隐藏加载态');
